using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SBCCashier.Web.Models;using SBCCashier.Web.Services;
namespace SBCCashier.Web.Pages.Payments;
public sealed class IndexModel:PageModel{private readonly CashierStore _store;public IReadOnlyList<PaymentRow> Payments{get;private set;}=[];public IReadOnlyList<Student> Students{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public Payment NewPayment{get;set;}=new();public IndexModel(CashierStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(NewPayment.Amount<=0||string.IsNullOrWhiteSpace(NewPayment.Description)){ErrorMessage="Payment description and amount are required.";Load();return Page();}try{_store.AddPayment(NewPayment);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load(){Payments=_store.Payments;Students=_store.Students;}}
